 * Find a contact by email on an arbitrary list.
 */
async getContactOnList(
  listId: string,
  email: string,
): Promise<ContactData | undefined> {
  const result = await this.request(
    "GET",
    `/lists/${listId}/contacts?filter=${encodeURIComponent(`email==${email}`)}`,
  );
  if (!result.ok) return undefined;
  const data = result.data as { data?: ContactData[] };
  const contacts = data?.data ?? [];
  return contacts.length > 0 ? contacts[0] : undefined;
}

/**
 * Apply tags to a contact on an arbitrary list.
 */
async tagContactOnList(
  listId: string,
  contactId: number,
  tags: string[],
): Promise<{ ok: boolean; error?: string }> {
  const result = await this.request(
    "POST",
    `/lists/${listId}/contacts/${contactId}/tag`,
    { tags },
  );
  return { ok: result.ok, error: result.error };
}

/**
 * Import a Drip-migrated contact: create the contact on the target list WITHOUT
 * sending a double-opt-in confirmation email, then apply the given tags.
 *
 * If the contact already exists on the list, skip entirely — no writes, no
 * tag changes. Phased runs against the live list are therefore idempotent:
 * a second pass leaves previously-imported contacts untouched.
 *
 * The `send_double_opt_in=false` flag is hardcoded here and asserted before the
 * request fires. Never expose a toggle; a stray `true` re-confirmation run
 * collapses the list.
 */
async importContact(
  listId: string,
  email: string,
  customAttributes: Record<string, string>,
  tags: string[],
): Promise<{ ok: boolean; contactId?: number; skipped?: boolean; error?: string }> {
  const createPath = `/lists/${listId}/contacts?send_double_opt_in=false`;
  if (!createPath.includes("send_double_opt_in=false")) {
    throw new Error("Refusing to import: DOI=false flag missing from request path");
  }

  const existing = await this.getContactOnList(listId, email);
  if (existing?.id) {
    return { ok: true, contactId: existing.id, skipped: true };
  }

  const payload = {
    email,
    custom_attributes: this.attrsToArray(customAttributes),
  };
  const create = await this.request("POST", createPath, payload);
  if (!create.ok) return { ok: false, error: create.error };
  const data = create.data as { data?: { id?: number }; id?: number };
  const contactId = data?.data?.id ?? data?.id;
  if (!contactId) return { ok: false, error: "create returned no contact id" };

  if (tags.length > 0) {
    const tagResult = await this.tagContactOnList(listId, contactId, tags);
    if (!tagResult.ok) {
      return { ok: false, contactId, error: `tag failed: ${tagResult.error}` };
    }
  }

  return { ok: true, contactId };
}

