import "./load-env";
import { CakemailClient } from "./cakemail-client";

async function main() {
  const c = new CakemailClient();

  // 1. How many contacts are on Course Students?
  const all = await c.rawRequest("GET", "/lists/9403583/contacts?per_page=200");
  const ad = all.data as any;
  console.log(`Course Students total (page 1, per_page=200): ${ad?.data?.length ?? 0}`);
  console.log(`Pagination:`, JSON.stringify(ad?.pagination));

  // 2. Show each contact with their custom attributes.
  for (const contact of ad?.data ?? []) {
    const attrs = (contact.custom_attributes ?? [])
      .map((a: any) => `${a.name}=${a.value}`)
      .join(", ");
    console.log(`  id=${contact.id}  ${contact.email}`);
    if (attrs) console.log(`    attrs: ${attrs}`);
  }

  // 3. Verify the fix by looking up a specific email.
  const probe = await c.getContact("mark@agilepainrelief.com");
  console.log(`\ngetContact("mark@agilepainrelief.com"):`, probe ? `found id=${probe.id}` : "not found");
  const bogus = await c.getContact("definitely-not-real-xyz-123@nowhere.invalid");
  console.log(`getContact("bogus@..."):`, bogus ? "FOUND (bug!)" : "not found (OK)");
}

main().catch((e) => { console.error(e); process.exit(1); });

