import {
  CAKEMAIL_API_BASE,
  COURSE_STUDENTS_LIST_ID,
  POSTCOURSE_CSM_LIST_ID,
  SENDER_ID_CONTACT,
  EMAIL_FROM_NAME,
  EMAIL_FROM_EMAIL,
} from "../../shared/cakemail-constants";

const TOKEN_URL = `${CAKEMAIL_API_BASE}/token`;

interface SendRecipient {
  email: string;
  name: string;
}

interface SendOptions {
  subject: string;
  htmlBody: string;
  recipient: SendRecipient;
  tags?: string[];
  trackOpens?: boolean;
  trackClicks?: boolean;
  /**
   * Verified sender ID to send from. Defaults to `SENDER_ID_CONTACT` (contact@,
   * used for transactional course emails). Pass `SENDER_ID_MARK` for promos that
   * should come from Mark personally (e.g. refresher-seat offers).
   */
  senderId?: string;
}

interface SendResult {
  ok: boolean;
  emailId?: string;
  error?: string;
}

interface ContactData {
  id?: number;
  email: string;
  custom_attributes?: Array<{ name: string; value: string }>;
}

export class CakemailClient {
  private refreshToken: string;
  private accessToken: string | null = null;
  private accessTokenExpiry = 0;
  private fromEmail: string;
  private fromName: string;

  constructor() {
    const refreshToken = process.env.CAKEMAIL_REFRESH_TOKEN;
    if (!refreshToken) throw new Error("CAKEMAIL_REFRESH_TOKEN not set in .env");

    this.refreshToken = refreshToken;
    this.fromEmail = EMAIL_FROM_EMAIL;
    this.fromName = EMAIL_FROM_NAME;
  }

  private async getAccessToken(): Promise<string> {
    // Return cached token if still valid (with 60s buffer)
    if (this.accessToken && Date.now() < this.accessTokenExpiry - 60_000) {
      return this.accessToken;
    }

    const body = new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: this.refreshToken,
    });

    const res = await fetch(TOKEN_URL, { method: "POST", body });

    if (!res.ok) {
      const text = await res.text();
      if (res.status === 401 || res.status === 403) {
        throw new Error(
          `Cakemail refresh token expired. Run: npm run refresh-cakemail\n${text}`,
        );
      }
      throw new Error(`Cakemail token refresh failed (${res.status}): ${text}`);
    }

    const data = (await res.json()) as {
      access_token: string;
      refresh_token: string;
      expires_in: number;
    };

    this.accessToken = data.access_token;
    this.accessTokenExpiry = Date.now() + data.expires_in * 1000;

    // If a new refresh token was issued, auto-update .env
    if (data.refresh_token && data.refresh_token !== this.refreshToken) {
      this.refreshToken = data.refresh_token;
      this.updateEnvRefreshToken(data.refresh_token);
    }

    return this.accessToken;
  }

  private async request(
    method: string,
    path: string,
    body?: unknown,
  ): Promise<{ ok: boolean; status: number; data?: unknown; error?: string }> {
    const maxAttempts = 4;
    let lastError = "";
    let lastStatus = 0;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      const token = await this.getAccessToken();

      const headers: Record<string, string> = {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      };

      const init: RequestInit = { method, headers };

