import { isScored } from './types';
import type {
  MapMoveConfig,
  MapMoveEntry,
  MapMoveResult,
  MapMoveShape,
  QuizData,
  QuizResponses,
} from './types';

/**
 * The `mapMove` copy with the taker's role variant applied, if the quiz
 * declares any. The role is read from the `tag` on the profile question's
 * chosen option, which is the same tag the submission carries, so there is one
 * identifier per role rather than two that can drift.
 *
 * Only fields the variant actually supplies replace the base; everything else
 * falls through, so a variant is a patch rather than a second full copy of the
 * block.
 */
export function resolveMapMoveCopy(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveConfig | undefined {
  const config = quiz.mapMove;
  const roleVariants = config?.roleVariants;
  if (!config || !roleVariants) return config;

  const question = quiz.questions.find(
    (q) => q.id === roleVariants.profileQuestion
  );
  if (!question) return config;

  const tag = question.options[responses[question.id] ?? -1]?.tag;
  const variant = tag ? roleVariants.variants[tag] : undefined;
  if (!variant) return config;

  const overrides = Object.fromEntries(
    Object.entries(variant).filter(([, value]) => value !== undefined)
  );
