import clsx from 'clsx';

import NewsletterImage from '@/assets/images/newsletter/newsletter-white.png';
import NewsletterImageSidebar from '@/assets/images/newsletter/newsletter.png';

import { zodResolver } from '@hookform/resolvers/zod';
import { useForm } from 'react-hook-form';
import { z } from 'zod';

import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { useRef, useState } from 'react';
import { appendSignupTags } from '@/lib/newsletter-tags';
import { SignupType, SignupSource } from '@/constants/signup';
import Turnstile, { type TurnstileHandle } from '@/components/global/turnstile';

const newsletterFormSchema = z.object({
  firstName: z.string().min(1, {
    message: 'First name is required.',
  }),
  lastName: z.string().min(1, {
    message: 'Last name is required.',
  }),

  email: z.email({
    message: 'Invalid email address.',
  }),
});

export type FormSubmissionProps = {
  heading?: string;
  body?: string;
  disclaimer?: string;
  includeImage?: boolean;
  /**
   * Visual arrangement of the form, independent of where it's placed: `card` is
   * the large rounded boxed form, `compact` is the slim form used in tight
   * spaces like the modal popup. (Placement attribution is `source`, not this.)
   */
  layout?: 'card' | 'compact';
  /** Which signup widget this is — drives the `Signup*` type tag. */
  signupType?: SignupType;
  /** Which page this form sits on — drives the `From*` source tag. */
  source?: SignupSource;
};

export default function FormSubmission({
  heading = 'Become the Scrum Fixer',
  body = 'Join the Agile Pain Relief newsletter for practical, evidence-based guidance on Effective Scrum and how teams actually deliver.',
  disclaimer = `We care about your data, view <a href="/privacy-policy" class="underline">privacy policy</a>.`,
  includeImage = false,
  layout = 'card',
  signupType = SignupType.Inline,
  source = SignupSource.Other,
}: FormSubmissionProps) {
  const [loading, setLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [token, setToken] = useState('');
  const [submitError, setSubmitError] = useState('');
  const turnstileRef = useRef<TurnstileHandle>(null);

  const form = useForm<z.infer<typeof newsletterFormSchema>>({
    resolver: zodResolver(newsletterFormSchema),
    defaultValues: {
      firstName: '',
      lastName: '',
      email: '',
    },
  });

  const onSubmit = async (values: z.infer<typeof newsletterFormSchema>) => {
    setLoading(true);
    setSubmitError('');

    // Cloudflare Turnstile token is required: our endpoint verifies it before
    // forwarding to Cakemail. It usually arrives well before submit; if not,
    // ask the user to wait a beat.
    if (!token) {
      setSubmitError(
        'Please wait a moment for the verification to finish, then try again.'
      );
      setLoading(false);
      return;
    }

    // POST same-origin to our Turnstile-gated endpoint, which verifies the token
    // and forwards to the Cakemail hosted form server-side. (The raw Cakemail URL
    // is no longer in the client bundle, so bots can't scrape it from the page.)
    const formData = new FormData();
    formData.append('email', values.email.trim());
    formData.append('custom_attributes[firstname]', values.firstName.trim());
    formData.append('custom_attributes[lastname]', values.lastName.trim());
    // Type (this widget) + source (this page) tags, forwarded verbatim to the
    // Cakemail form's `tags[<name>]=true` dict.
    appendSignupTags(formData, { type: signupType, source });
    formData.append('form', 'newsletter');
    formData.append('cf-turnstile-response', token);

    try {
      const response = await fetch('/api/newsletter-signup', {
        method: 'POST',
        body: formData,
      });
      if (!response.ok) {
        setSubmitError('We couldn’t verify your submission. Please try again.');
        setToken('');
        turnstileRef.current?.reset();
        setLoading(false);
        return;
      }
    } catch (err) {
      console.error('newsletter signup POST failed', err);
      setSubmitError('Something went wrong. Please try again.');
      setToken('');
      turnstileRef.current?.reset();
      setLoading(false);
      return;
    }

    form.reset();
    setToken('');
    turnstileRef.current?.reset();
    setIsSuccess(true);
    setLoading(false);
  };

  const inputClasses = clsx(
    'py-3!',
    layout === 'compact'
      ? 'bg-white h-10 text-base border-2 border-blue-200!'
      : 'bg-blue-100 border-2 text-lg! h-11 border-blue-800!'
  );

  return (
    <section className={clsx(layout === 'compact' ? '' : 'container mx-auto')}>
      <div
        className={clsx(
          layout === 'compact'
            ? ''
            : 'rounded-4xl bg-blue-200 px-5 py-10 sm:p-10'
        )}
      >
        <div
          className={clsx(
            'grid',
            includeImage
              ? layout === 'compact'
                ? 'grid-cols-1 gap-8'
                : 'grid-cols-1 gap-8 sm:gap-16 md:grid-cols-[40%_1fr]'
              : 'grid-cols-1'
          )}
        >
          {includeImage && (
            <img
              src={
                layout === 'compact'
                  ? NewsletterImageSidebar.src
                  : NewsletterImage.src
              }
              className="size-full max-h-90 object-contain"
              alt="Newsletter Image"
              loading="lazy"
            />
          )}
          <div
            className={clsx(
              includeImage
                ? 'flex flex-col gap-4'
                : 'grid grid-cols-1 gap-8 md:grid-cols-2 md:gap-32'
            )}
          >
            <div className="flex flex-col gap-2">
              <h2
                className={clsx(
                  layout === 'compact'
                    ? 'text-2xl/7'
                    : 'xs:text-4xl/8 text-3xl/8 md:text-5xl/12',
                  'font-bold'
                )}
                dangerouslySetInnerHTML={{ __html: heading }}
              />
              <p
                className={clsx(layout === 'compact' ? 'text-sm' : 'text-base')}
                dangerouslySetInnerHTML={{ __html: body }}
              />
            </div>

            {isSuccess ? (
              <div
                className={`rounded-lg border-2 border-green-700 bg-green-100 p-4 text-center text-green-900 ${
                  layout === 'compact' ? 'mx-auto max-w-2xl' : ''
                }`}
              >
                <h3
                  className={clsx(
                    layout === 'compact' ? 'text-lg' : 'text-2xl',
                    'font-bold'
                  )}
                >
                  Thanks! <br /> Just one last thing...
                </h3>
                <p
                  className={clsx(
                    layout === 'compact' ? 'text-sm' : 'text-base'
                  )}
                >
                  Check your inbox (or spam folder) and click on the
                  double-opt-in confirmation to complete your signup.
                </p>
              </div>
            ) : (
              <div className="my-2 flex flex-col gap-4">
                <div
                  className={layout === 'compact' ? 'mx-auto max-w-2xl' : ''}
                >
                  <Form {...form}>
                    <form
                      onSubmit={form.handleSubmit((values) => onSubmit(values))}
                      className={clsx(
                        layout === 'compact'
                          ? 'grid grid-cols-2 gap-3'
                          : 'grid grid-cols-2 gap-4'
                      )}
                    >
                      <FormField
                        control={form.control}
                        name="firstName"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="sr-only">
                              First Name
                            </FormLabel>
                            <FormControl>
                              <Input
                                className={inputClasses}
                                placeholder="First name"
                                {...field}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name="lastName"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="sr-only">Last Name</FormLabel>
                            <FormControl>
                              <Input
                                className={inputClasses}
                                placeholder="Last name"
                                {...field}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <div className="col-span-2">
                        <FormField
                          control={form.control}
                          name="email"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="sr-only">Email</FormLabel>
                              <FormControl>
                                <Input
                                  className={inputClasses}
                                  placeholder="your@email.com"
                                  {...field}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                      <div className="col-span-2">
                        <Turnstile
                          ref={turnstileRef}
                          onToken={setToken}
                          onExpire={() => setToken('')}
                        />
                      </div>
                      {submitError && (
                        <p className="col-span-2 text-sm text-red-700">
                          {submitError}
                        </p>
                      )}
                      <div className="col-span-2 w-full">
                        <Button
                          type="submit"
                          className="w-full"
                          disabled={loading}
                        >
                          {loading ? (
                            <div className="flex items-center gap-2">
                              <svg
                                className="size-5 animate-spin"
                                xmlns="http://www.w3.org/2000/svg"
                                fill="none"
                                viewBox="0 0 24 24"
                              >
                                <circle
                                  className="opacity-25"
                                  cx="12"
                                  cy="12"
                                  r="10"
                                  stroke="currentColor"
                                  strokeWidth="4"
                                />
                                <path
                                  className="opacity-75"
                                  fill="currentColor"
                                  d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                                />
                              </svg>
                              <span>Submitting...</span>
                            </div>
                          ) : (
                            'Subscribe'
                          )}
                        </Button>
                      </div>
                    </form>
                  </Form>
                </div>
                <p
                  className="text-sm"
                  dangerouslySetInnerHTML={{ __html: disclaimer }}
                />
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

