import { useRef, useState } from 'react';
import {
  appendSignupTags,
  sourceFromUtm,
  typeFromUtm,
} from '@/lib/newsletter-tags';
import { SignupType } from '@/constants/signup';
import Turnstile, { type TurnstileHandle } from '@/components/global/turnstile';

/**
 * Direct-download signup form for "AI Failure Modes for Agile Teams".
 *
 * Mirrors the AI quiz's capture step: it POSTs `email`,
 * `custom_attributes[firstname]`, and `tags[aiquiz]=true` as multipart form-data,
 * plus a Cloudflare Turnstile token, to our `/api/newsletter-signup` endpoint
 * (`form=ai`). That endpoint verifies the token and forwards to the Cakemail
 * Newsletter Subscribers form (double opt-in) server-side, so the raw Cakemail
 * URL isn't in the client bundle for bots to scrape. The `aiquiz` tag enrols them
 * in the ai-welcome nurture; the PDF is delivered by the ai-welcome email series
 * (email 01) after the contact confirms, not from this page.

    const formData = new FormData();
    formData.append('email', email.trim());
    if (firstName.trim()) {
      formData.append('custom_attributes[firstname]', firstName.trim());
    }
    // Destination form: tag from the origin the user came from, carried in the
    // link's UTM params (e.g. the homepage inline CTA → utm_source=home-page,
    // utm_medium=inline). Falls back to `inline` when there's no UTM, since the
    // form itself is inline in page content. `aiquiz` rides along in the same
    // POST (the tag that enrols them in the ai-welcome nurture).
    const params = new URLSearchParams(window.location.search);
    appendSignupTags(formData, {
      type: typeFromUtm(params.get('utm_medium'), SignupType.Inline),
      source: sourceFromUtm(params.get('utm_source')),
      extraTags: ['aiquiz'],
    });
    formData.append('form', 'ai');
    formData.append('cf-turnstile-response', token);

    // POST same-origin to our Turnstile-gated endpoint, which verifies the token
    // and forwards to the Cakemail AI form server-side.
    try {
      const response = await fetch('/api/newsletter-signup', {
        method: 'POST',
        body: formData,
      });
      if (!response.ok) {
        setSubmitError('We couldn’t verify your submission. Please try again.');
        setToken('');
        turnstileRef.current?.reset();
