    const init: RequestInit = { method, headers };

    if (body !== undefined) {
      headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(body);
    }

    const res = await fetch(`${CAKEMAIL_API_BASE}${path}`, init);

    if (res.ok) {
      if (res.status === 204) {
        return { ok: true, status: 204 };
      }
      const data = await res.json();
      return { ok: true, status: res.status, data };
    }

    const text = await res.text();
    lastStatus = res.status;
    lastError = `${res.status} ${text}`;

    // Retry on 429 and 5xx; give up on 4xx client errors.
    const retryable = res.status === 429 || (res.status >= 500 && res.status < 600);
    if (!retryable || attempt === maxAttempts) {
      return { ok: false, status: res.status, error: lastError };
    }

    const retryAfter = Number(res.headers.get("retry-after"));
    const backoffMs = Number.isFinite(retryAfter) && retryAfter > 0
      ? retryAfter * 1000
      : 500 * Math.pow(2, attempt - 1);
    await new Promise((r) => setTimeout(r, backoffMs));
  }

  return { ok: false, status: lastStatus, error: lastError };
}

// --- Auth test ---

async testConnection(): Promise<{ ok: boolean; error?: string }> {
  const result = await this.request("GET", "/accounts/self");
  if (!result.ok) {
    return { ok: false, error: result.error };
  }
  return { ok: true };
}

// --- Transactional Email ---

async sendTransactional(options: SendOptions): Promise<SendResult> {
  const {
    subject,
    htmlBody,
    recipient,
    tags = [],
    trackOpens = true,
    trackClicks = true,
    senderId = SENDER_ID_CONTACT,
  } = options;

  const payload: Record<string, unknown> = {
    email: recipient.email,
    sender: { id: senderId },
    list_id: parseInt(COURSE_STUDENTS_LIST_ID, 10),
    content: {
      type: "transactional",
      subject,
      html: htmlBody,
      encoding: "utf-8",
    },
    track_opens: trackOpens,
    track_clicks: trackClicks,
  };

  if (tags.length > 0) {
    payload.tags = tags;
  }

  const result = await this.request("POST", "/v2/emails", payload);

  if (!result.ok) {
    return { ok: false, error: result.error };
  }

  const data = result.data as { data?: { id?: string } };
  return { ok: true, emailId: data?.data?.id };
}

// --- Helpers ---

/**
 * Convert a dict of custom attributes to the array format Cakemail expects:
 * {"key": "val"} -> [{"name": "key", "value": "val"}]
 */
private attrsToArray(
