export const CAKEMAIL_API_BASE = 'https://api.cakemail.dev';

export const COURSE_STUDENTS_LIST_ID = '9403583';
export const POSTCOURSE_CSM_LIST_ID = '9403585';
export const NEWSLETTER_SUBSCRIBERS_LIST_ID = '9402690';

export const SENDER_ID_CONTACT = 'I8zsXnsWkDfOhTMPXWhE';
export const SENDER_ID_MARK = 'Qbphvqz44Uilcu8pd12G';

// Visible sender identity used in email footers (the From name/address recipients
// see on every email). Not secret. Shared by the API client and the markdown/MJML
// renderer. The deliverability-relevant sender is the verified SENDER_ID_* above,
// which the send API actually uses; these two are display strings only.
export const EMAIL_FROM_NAME = 'Mark Levison';
export const EMAIL_FROM_EMAIL = 'mark@agilepainrelief.com';

// The Cakemail hosted-form submission URLs moved to src/lib/server/cakemail-forms.ts
// (SERVER-ONLY). They used to be POSTed to directly from the browser, which put the
// raw URLs in the client bundle where bots scraped them and submitted junk. Browser
// signups now POST to the Turnstile-gated /api/newsletter-signup endpoint, which
// verifies the challenge and forwards to Cakemail server-side.
//
// The quiz (src/lib/quiz-engine/, APR-agnostic) still POSTs browser-direct using its
