 * (`newsletter` | `ai` | `quiz`, sent by the client) currently maps to the one
 * consolidated form; the parameter is kept so a purpose can be split back onto
 * its own form later by returning a different URL here.
 */
export function cakemailFormUrlFor(_target: string | null): string {
  return CAKEMAIL_FORM_URL;
