/**
 * Get a custom attribute value for a contact on the Course Students list.
 */
async getContactAttribute(
  email: string,
  attributeName: string,
): Promise<string | undefined> {
  const contact = await this.getContact(email);
  if (!contact) return undefined;
  const attr = contact.custom_attributes?.find((a) => a.name === attributeName);
  return attr?.value;
}

/**
 * Create a contact on the Course Students list with optional custom attributes.
 */
async createContact(
  email: string,
  customAttributes?: Record<string, string>,
): Promise<{ ok: boolean; contactId?: number; error?: string }> {
  const payload: Record<string, unknown> = { email };
  if (customAttributes) {
    payload.custom_attributes = this.attrsToArray(customAttributes);
  }

  const result = await this.request(
    "POST",
    `/lists/${COURSE_STUDENTS_LIST_ID}/contacts?send_double_opt_in=false`,
    payload,
  );

  if (!result.ok) {
    return { ok: false, error: result.error };
  }

  const data = result.data as { data?: { id?: number } };
  return { ok: true, contactId: data?.data?.id };
}

/**
 * Update custom attributes on an existing contact on the Course Students list.
 */
async updateContact(
  contactId: number,
  customAttributes: Record<string, string>,
): Promise<{ ok: boolean; error?: string }> {
  const result = await this.request(
    "PATCH",
    `/lists/${COURSE_STUDENTS_LIST_ID}/contacts/${contactId}`,
    { custom_attributes: this.attrsToArray(customAttributes) },
  );

  return { ok: result.ok, error: result.error };
}

/**
 * Create or update a contact on the Course Students list.
 * If the contact already exists, updates their custom attributes.
 * Returns the contact ID.
 */
async upsertContact(
  email: string,
  customAttributes: Record<string, string>,
): Promise<{ ok: boolean; contactId?: number; error?: string }> {
  const existing = await this.getContact(email);

  if (existing?.id) {
    const updateResult = await this.updateContact(existing.id, customAttributes);
    return { ok: updateResult.ok, contactId: existing.id, error: updateResult.error };
  }

  return this.createContact(email, customAttributes);
}

// --- Tags ---

/**
 * Tag a contact on the Course Students list.
 */
async tagContact(
  contactId: number,
  tags: string[],
): Promise<{ ok: boolean; error?: string }> {
  // Endpoint is `/tag` (singular), not `/tags`. Prior use of `/tags` silently
  // 404'd on every course-email send; see Cakemail OpenAPI.
  const result = await this.request(
    "POST",
    `/lists/${COURSE_STUDENTS_LIST_ID}/contacts/${contactId}/tag`,
    { tags },
  );

  return { ok: result.ok, error: result.error };
}

