import "./load-env";
import { CakemailClient } from "./cakemail-client";
import {
  SIGNUP_STAGING_LIST_ID,
  NEWSLETTER_SUBSCRIBERS_LIST_ID,
} from "../../shared/cakemail-constants";

/**
 * Move confirmed signups off the staging list and onto Newsletter Subscribers.
 *
 * Why staging exists: a Cakemail hosted-form POST REPLACES a contact's entire
 * tag set rather than merging it, and Newsletter Subscribers holds ~3,650
 * Drip-migrated contacts carrying alumni / interest / refresher-suppression
 * tags. One form submission from any of them would wipe the lot. So browser
 * forms now write to the staging list, where a contact has no history to lose,
 * and this job carries them across through the authenticated API — whose `/tag`
 * endpoint MERGES. See the tag-hazard section in the root CLAUDE.md.
 *
 * Idempotent: a migrated contact is stamped with a `migrated_at` custom
 * attribute on the staging list and skipped on later runs. Safe to run as often
 * as you like; the intended cadence is weekly, alongside the newsletter.
 *
 *   npm run migrate-signups                 # dry run: report only, no writes
 *   npm run migrate-signups -- --apply      # perform the migration
 *   npm run migrate-signups -- --verbose    # also dump the first raw contact
 *   npm run migrate-signups -- --limit 5    # cap how many are processed
 */

const MIGRATED_ATTR = "migrated_at";

interface StagedContact {
  id: number;
  email: string;
  status: string;
  attributes: Record<string, string>;
  tags: string[];
  raw: Record<string, unknown>;
}

/**
 * Cakemail has returned tags as bare strings and as objects with a `name` in
 * different endpoints, so accept both rather than guessing. Anything else is
 * dropped instead of being stringified into a junk tag.
 */
function normaliseTags(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((tag) => {
      if (typeof tag === "string") return tag;
      if (tag && typeof tag === "object" && "name" in tag) {
        const name = (tag as { name?: unknown }).name;
        return typeof name === "string" ? name : "";
      }
      return "";
    })
    .filter((tag) => tag.length > 0);
}

function normaliseAttributes(value: unknown): Record<string, string> {
  if (!Array.isArray(value)) return {};
  const out: Record<string, string> = {};
  for (const attr of value) {
    if (attr && typeof attr === "object" && "name" in attr) {
      const { name, value: v } = attr as { name?: unknown; value?: unknown };
      if (typeof name === "string" && v != null) out[name] = String(v);
    }
  }
  return out;
}

function toStagedContact(raw: Record<string, unknown>): StagedContact | null {
  const id = typeof raw.id === "number" ? raw.id : undefined;
  const email = typeof raw.email === "string" ? raw.email : undefined;
  if (id === undefined || !email) return null;
  return {
    id,
    email,
    status: typeof raw.status === "string" ? raw.status : "unknown",
    attributes: normaliseAttributes(raw.custom_attributes),
    tags: normaliseTags(raw.tags),
    raw,
  };
}

async function fetchStaged(client: CakemailClient): Promise<StagedContact[]> {
  const all: StagedContact[] = [];
  const perPage = 200;
  for (let page = 1; ; page++) {
    const result = await client.listContactsOnList(
      SIGNUP_STAGING_LIST_ID,
      page,
      perPage,
    );
    if (!result.ok) {
      throw new Error(`Failed to read staging list page ${page}: ${result.error}`);
    }
    for (const raw of result.contacts) {
      const contact = toStagedContact(raw);
      if (contact) all.push(contact);
    }
    if (result.contacts.length < perPage) break;
  }
  return all;
}

async function main() {
  const args = process.argv.slice(2);
  const apply = args.includes("--apply");
  const verbose = args.includes("--verbose");
  const limitArg = args.indexOf("--limit");
  const limit =
    limitArg !== -1 && args[limitArg + 1] ? parseInt(args[limitArg + 1], 10) : Infinity;

  if (!SIGNUP_STAGING_LIST_ID) {
    console.error(
      "SIGNUP_STAGING_LIST_ID is empty in shared/cakemail-constants.ts.\n" +
        'Create the list first: npm run create-list -- "Signup Staging", then paste the id.',
    );
    process.exit(1);
  }

  const client = new CakemailClient();
  const staged = await fetchStaged(client);

