  console.log(`Staging list ${SIGNUP_STAGING_LIST_ID}: ${staged.length} contacts`);
  console.log(`  by status: ${JSON.stringify(statusCounts)}`);
  console.log(`  already migrated: ${alreadyMigrated.length}`);
  console.log(`  eligible (active, not yet migrated): ${pending.length}`);
  if (toProcess.length < pending.length) {
    console.log(`  capped by --limit: processing ${toProcess.length}`);
  }
  console.log(apply ? "\nMode: APPLY\n" : "\nMode: dry run (use --apply to write)\n");

  const today = new Date().toISOString().slice(0, 10);
  let migrated = 0;
  let failed = 0;

  for (const contact of toProcess) {
    const attrs: Record<string, string> = {};
    for (const key of ["firstname", "lastname"]) {
      if (contact.attributes[key]) attrs[key] = contact.attributes[key];
    }
    const summary =
      `${contact.email}` +
      (contact.tags.length ? ` tags=[${contact.tags.join(", ")}]` : " tags=[]") +
      (Object.keys(attrs).length ? ` attrs=${JSON.stringify(attrs)}` : "");

    if (!apply) {
      console.log(`  would migrate: ${summary}`);
      migrated++;
      continue;
    }

    // Create on Newsletter Subscribers without a second double opt-in: consent
    // was given on the staging form, which says in so many words that they're
    // subscribing to the newsletter. `importContact` returns the existing id
    // untouched if they're already on the list.
    const imported = await client.importContact(
      NEWSLETTER_SUBSCRIBERS_LIST_ID,
