      console.error(`  FAILED (create): ${contact.email} — ${imported.error}`);
      failed++;
      continue;
    }

    // Additive: this is the whole reason the migration goes through the API
    // rather than a form. Never replace here.
    if (contact.tags.length > 0) {
      const tagged = await client.tagContactOnList(
        NEWSLETTER_SUBSCRIBERS_LIST_ID,
        imported.contactId,
        contact.tags,
      );
      if (!tagged.ok) {
        // Stop short of stamping: leaving them unstamped means the next run
        // retries the tags rather than declaring them done.
        console.error(`  FAILED (tag): ${contact.email} — ${tagged.error}`);
        failed++;
        continue;
      }
    }

    const stamped = await client.updateContactOnList(
      SIGNUP_STAGING_LIST_ID,
      contact.id,
      { [MIGRATED_ATTR]: today },
    );
    if (!stamped.ok) {
      // The contact IS migrated; only the marker failed. Say so loudly, because
      // the next run will migrate them again — harmless (create is a no-op and
      // tags merge) but confusing if unexplained.
      console.error(
        `  WARNING: migrated ${contact.email} but could not stamp ${MIGRATED_ATTR} — ${stamped.error}`,
      );
    }

    console.log(`  migrated: ${summary}`);
    migrated++;
  }

  console.log(
    `\n${apply ? "Migrated" : "Would migrate"}: ${migrated}` +
      (failed ? `, failed: ${failed}` : ""),
  );
  if (failed) process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
