 * `npm run migrate-signups` then carries them onto Newsletter Subscribers through
 * the authenticated API, which merges. See the tag-hazard section in CLAUDE.md.
 */
export const CAKEMAIL_STAGING_FORM_URL = '';

/**
 * How a destination treats the `tags[<name>]=true` fields the client sent.
 * `strip` is not a nicety: a tagged POST to a Newsletter Subscribers form
 * silently destroys that contact's existing tags.
 */
export type TagPolicy = 'forward' | 'strip';

/**
 * Resolve where a signup goes and whether its tags may travel with it.
 *
 * - `newsletter` — straight onto Newsletter Subscribers, tags STRIPPED. These
 *   forms make a plain subscribe promise ("get your free copy", "join the
 *   waitlist") and are answered by the single welcome email that triggers on
 *   list-add. Their `Signup*` / `From*` tags have no consumer, and forwarding
 *   them would wipe whatever the contact already carries.
 * - `ai` / `quiz` — onto the staging list, tags forwarded. Harmless there, and
 *   the sequence and the migration both read them.
 *
 * Unknown or missing values fall through to the safe destination.
 */
export function cakemailFormFor(target: string | null): {
  url: string;
  tagPolicy: TagPolicy;
} {
  if (target === 'ai' || target === 'quiz') {
    // Fail SOFT, not closed: without a staging form we still take the signup —
    // on the main list, with tags stripped, so nothing is destroyed. Losing the
    // person would be worse than losing their sequence, but this is a
    // misconfiguration and needs to be shouted about.
    if (!CAKEMAIL_STAGING_FORM_URL) {
      console.error(
        `CAKEMAIL_STAGING_FORM_URL is unset; routing "${target}" signup to the main list untagged. ` +
          'The lead-magnet sequence will NOT fire for this contact.'
      );
      return { url: CAKEMAIL_FORM_URL, tagPolicy: 'strip' };
    }
    return { url: CAKEMAIL_STAGING_FORM_URL, tagPolicy: 'forward' };
  }
  return { url: CAKEMAIL_FORM_URL, tagPolicy: 'strip' };
}

