import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { SENDER_ID_MARK } from "../../shared/cakemail-constants";

/**
 * One-shot: create a new Cakemail list via the API. Prints the new list ID
 * so it can be added to shared/cakemail-constants.ts.
 *
 * Usage:
 *   npm run create-list -- "AI Quiz Subscribers"
 */

async function main() {
  const name = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (!name) {
    console.error('Usage: npm run create-list -- "<list name>"');
    process.exit(1);
  }

  const client = new CakemailClient();

  console.log(`Creating list: "${name}"`);
  const result = await client.rawRequest("POST", "/lists", {
    name,
    default_sender: { id: SENDER_ID_MARK },
    language: "en_US",
  });

  if (!result.ok) {
    const detail =
      result.error ?? (result.data ? JSON.stringify(result.data) : "(no body)");
    console.error(`\nFailed (${result.status}): ${detail}`);
    process.exit(1);
  }

  // Cakemail returns either {data: {id: ...}} or {id: ...} depending on endpoint
  const body = result.data as
    | { data?: { id?: string | number }; id?: string | number }
    | undefined;
  const id = body?.data?.id ?? body?.id;
  if (id == null) {
    console.error(`\nUnexpected response shape: ${JSON.stringify(body)}`);
    process.exit(1);
  }

  console.log(`\nCreated. List ID: ${id}`);
  console.log(`\nAdd to shared/cakemail-constants.ts:`);
  const constantName = name
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  console.log(`export const ${constantName}_LIST_ID = "${id}";`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
