import "./load-env";
import {
  NEWSLETTER_SUBSCRIBERS_LIST_ID,
  SIGNUP_STAGING_LIST_ID,
} from "../../shared/cakemail-constants";
import { CakemailClient } from "./cakemail-client";

/**
 * One-shot: register the custom attributes used by the signup lists. Run after
 * the initial Cakemail setup and any time a new attribute is added to the plan.
 *
 * Attributes are list-scoped and must exist before anything can set them, so
 * this has to run on a newly created list BEFORE its hosted form takes a
 * submission (the form sends `custom_attributes[firstname]`) and before
 * `migrate-signups` stamps `migrated_at`.
 */

async function main() {
  const client = new CakemailClient();

  await client.ensureCustomAttributes(NEWSLETTER_SUBSCRIBERS_LIST_ID, [
    { name: "firstname", type: "text" },
    { name: "lastname", type: "text" },
    { name: "drip_migrated", type: "text" },
    { name: "migrated_at", type: "text" },
  ]);
  console.log(
    `Custom attributes ensured on Newsletter Subscribers list (${NEWSLETTER_SUBSCRIBERS_LIST_ID}): firstname, lastname, drip_migrated, migrated_at`,
  );

  if (!SIGNUP_STAGING_LIST_ID) {
    console.log(
      "\nSIGNUP_STAGING_LIST_ID is empty — skipping the staging list.\n" +
        'Create it with: npm run create-list -- "Signup Staging", paste the id into\n' +
        "shared/cakemail-constants.ts, then re-run this command.",
    );
    return;
  }

  // `migrated_at` here is the marker migrate-signups writes back to the STAGING
  // contact once they have been carried over, which is what makes re-runs
  // idempotent. Same attribute name as on Newsletter Subscribers, different
  // list, different meaning — attributes are list-scoped, so they never collide.
  await client.ensureCustomAttributes(SIGNUP_STAGING_LIST_ID, [
    { name: "firstname", type: "text" },
    { name: "lastname", type: "text" },
    { name: "migrated_at", type: "text" },
  ]);
  console.log(
    `Custom attributes ensured on Signup Staging list (${SIGNUP_STAGING_LIST_ID}): firstname, lastname, migrated_at`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

