import "./load-env";
import { CakemailClient } from "./cakemail-client";
import {
  SIGNUP_STAGING_LIST_ID,
  NEWSLETTER_SUBSCRIBERS_LIST_ID,
} from "../../shared/cakemail-constants";

// READ-ONLY probe: can Cakemail forms be listed (and therefore maybe created)
// through the API, or is the GUI the only way? Also confirms the staging list
// exists and reports its custom attributes.
async function main() {
  const c = new CakemailClient();

  const paths = [
    "/forms",
    `/forms?filter=${encodeURIComponent(`list_id==${NEWSLETTER_SUBSCRIBERS_LIST_ID}`)}`,
    `/lists/${NEWSLETTER_SUBSCRIBERS_LIST_ID}/forms`,
    `/lists/${SIGNUP_STAGING_LIST_ID}/forms`,
    `/lists/${SIGNUP_STAGING_LIST_ID}`,
    `/lists/${SIGNUP_STAGING_LIST_ID}/attributes`,
  ];

  for (const path of paths) {
    const res = await c.rawRequest("GET", path);
    const body = JSON.stringify(res.data ?? res.error ?? "").slice(0, 900);
    console.log(`\n=== GET ${path}\n    status ${res.status} ok=${res.ok}\n    ${body}`);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

