import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { SIGNUP_STAGING_LIST_ID } from "../../shared/cakemail-constants";

/**
 * One-shot: create the hosted signup form on the Signup Staging list by cloning
 * the live "Newsletter Signup" form.
 *
 * Cakemail forms ARE an API resource (`/forms`), despite the UI being the usual
 * route — so this needs no GUI. It clones rather than builds because a form's
 * `content` is a BEE page-builder document that declares the fields; hand-rolling
 * one risks a submission endpoint that rejects `custom_attributes[firstname]`.
 * We never render the form anyway: the site only ever POSTs to its
 * `submission_url`.
 *
 * Prints the new `submission_url` to paste into CAKEMAIL_STAGING_FORM_URL in
 * src/lib/server/cakemail-forms.ts.
 *
 *   npm run create-staging-form              # dry run: show what would be sent
 *   npm run create-staging-form -- --apply   # create it
 */

const SOURCE_FORM_NAME = "Newsletter Signup";
const NEW_FORM_NAME = "Signup Staging";

interface CakemailForm {
  id: string;
  name: string;
  list_id: number;
  enabled?: boolean;
  double_opt_in?: boolean;
  double_opt_in_redirect_url?: string | null;
  post_redirect_url?: string | null;
  async_processing?: boolean;
  branding?: string;
  submission_url?: string;
  content?: unknown;
}

async function main() {
  const apply = process.argv.slice(2).includes("--apply");

  if (!SIGNUP_STAGING_LIST_ID) {
    console.error(
      'SIGNUP_STAGING_LIST_ID is empty. Run: npm run create-list -- "Signup Staging"',
    );
    process.exit(1);
  }

  const client = new CakemailClient();

  const listRes = await client.rawRequest("GET", "/forms");
  if (!listRes.ok) {
    console.error(`Could not list forms: ${listRes.error}`);
    process.exit(1);
  }
  const forms = (listRes.data as { data?: CakemailForm[] })?.data ?? [];

  const existingStaging = forms.find(
    (f) => f.list_id === parseInt(SIGNUP_STAGING_LIST_ID, 10),
  );
  if (existingStaging) {
    console.log(
      `A form already exists on the staging list: "${existingStaging.name}" (${existingStaging.id})`,
    );
    console.log(`submission_url: ${existingStaging.submission_url ?? "(unpublished)"}`);
    console.log("\nNothing to do. Delete it in Cakemail first if you want a fresh one.");
    return;
  }

  const source = forms.find((f) => f.name === SOURCE_FORM_NAME);
  if (!source) {
    console.error(
      `Could not find the source form "${SOURCE_FORM_NAME}". Forms present: ${forms
        .map((f) => f.name)
        .join(", ")}`,
    );
    process.exit(1);
  }

  const detailRes = await client.rawRequest("GET", `/forms/${source.id}`);
  if (!detailRes.ok) {
    console.error(`Could not read form ${source.id}: ${detailRes.error}`);
    process.exit(1);
  }
  const detail = (detailRes.data as { data?: CakemailForm })?.data;
  if (!detail?.content) {
    console.error("Source form has no content to clone.");
    process.exit(1);
  }

  const payload = {
    name: NEW_FORM_NAME,
    list_id: parseInt(SIGNUP_STAGING_LIST_ID, 10),
    enabled: true,
    // Double opt-in is the consent record for the later migration onto
    // Newsletter Subscribers, which skips a second confirmation. Never turn
    // this off.
    double_opt_in: true,
    double_opt_in_redirect_url: detail.double_opt_in_redirect_url ?? null,
    post_redirect_url: detail.post_redirect_url ?? null,
    async_processing: detail.async_processing ?? true,
    branding: detail.branding ?? "basic",
    content: detail.content,
  };

  console.log(`Cloning "${source.name}" (${source.id}) onto list ${SIGNUP_STAGING_LIST_ID}`);
  console.log(
    JSON.stringify({ ...payload, content: "<cloned BEE document, omitted>" }, null, 2),
  );

  if (!apply) {
    console.log("\nDry run. Re-run with --apply to create it.");
    return;
  }

  const created = await client.rawRequest("POST", "/forms", payload);
  if (!created.ok) {
    console.error(`\nFailed (${created.status}): ${created.error}`);
    process.exit(1);
  }
  const newForm = (created.data as { data?: CakemailForm })?.data;
  if (!newForm?.id) {
    console.error(`\nUnexpected response: ${JSON.stringify(created.data)}`);
    process.exit(1);
  }
  console.log(`\nCreated form ${newForm.id}`);

  // A form only gets a submission_url once published. If the create response
  // didn't include one, try publishing, then re-read.
  let submissionUrl = newForm.submission_url;
  if (!submissionUrl) {
    const published = await client.rawRequest("POST", `/forms/${newForm.id}/publish`);
    if (!published.ok) {
      console.error(
        `\nCreated, but publishing failed (${published.status}): ${published.error}\n` +
          "Publish it in the Cakemail UI and read the submission URL from there.",
      );
      process.exit(1);
    }
    const reread = await client.rawRequest("GET", `/forms/${newForm.id}`);
    submissionUrl = (reread.data as { data?: CakemailForm })?.data?.submission_url;
  }

  if (!submissionUrl) {
    console.error("\nCreated and published, but no submission_url came back. Check the UI.");
    process.exit(1);
  }

  console.log(`\nPaste into CAKEMAIL_STAGING_FORM_URL in src/lib/server/cakemail-forms.ts:`);
  console.log(`\n  '${submissionUrl}'`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

