import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { SIGNUP_STAGING_LIST_ID } from "../../shared/cakemail-constants";

// Narrow down why POST /forms 500s: try progressively richer payloads and an
// alternate path, stopping at the first success. Any form this creates is left
// in place for inspection (and is deletable).
async function main() {
  const c = new CakemailClient();
  const listId = parseInt(SIGNUP_STAGING_LIST_ID, 10);

  const attempts: Array<{ label: string; path: string; body: unknown }> = [
    { label: "minimal, /forms", path: "/forms", body: { name: "Signup Staging", list_id: listId } },
    { label: "minimal, /lists/{id}/forms", path: `/lists/${listId}/forms`, body: { name: "Signup Staging" } },
    {
      label: "with opt-in settings, /forms",
      path: "/forms",
      body: {
        name: "Signup Staging",
        list_id: listId,
        enabled: true,
        double_opt_in: true,
      },
    },
  ];

  for (const attempt of attempts) {
    const res = await c.rawRequest("POST", attempt.path, attempt.body);
    console.log(`\n=== ${attempt.label}`);
    console.log(`    status ${res.status} ok=${res.ok}`);
    console.log(`    ${JSON.stringify(res.data ?? res.error).slice(0, 600)}`);
    if (res.ok) {
      console.log("\n    SUCCESS — stopping here.");
      return;
    }
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

