import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { SIGNUP_STAGING_LIST_ID } from "../../shared/cakemail-constants";

// One live test submission against the staging subscription_forms endpoint,
// using the EXACT payload /api/newsletter-signup forwards, to confirm the
// endpoint accepts custom_attributes[...] and tags[...]=true.
const SUBMISSION_URL =
  "https://api.cakemail.dev/subscription_forms/ec093564ef759f5ab5fc1bedd07cfc496eb19406a4b3c42c3f9914a7aa6c9ce6abb9751b10d64a60745206070eba4314";
const TEST_EMAIL = "mark+staging1@agilepainrelief.com";

async function main() {
  const form = new FormData();
  form.append("email", TEST_EMAIL);
  form.append("custom_attributes[firstname]", "Mark");
  form.append("tags[sm-role-ai]", "true");
  form.append("tags[role-scrum-master]", "true");

  const res = await fetch(SUBMISSION_URL, { method: "POST", body: form });
  console.log(`POST ${SUBMISSION_URL.slice(0, 60)}...`);
  console.log(`  status ${res.status} ${res.statusText}`);
  console.log(`  body: ${(await res.text()).slice(0, 500)}`);

  // Give async_processing a moment, then read the contact back.
