import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { NEWSLETTER_SUBSCRIBERS_LIST_ID } from "../../shared/cakemail-constants";

/**
 * CONTROL EXPERIMENT. The staging submission 500s. Two candidate causes:
 *   (a) the staging list has policy_accepted: false
 *   (b) `subscription_forms/<hash>` endpoints don't work the way the older
 *       `form_submission/<hash>` one does
 *
 * This isolates them: create the SAME kind of endpoint on Newsletter
 * Subscribers, which has policy_accepted: true, and post a fresh alias to it.
 *   - works  => (a), the policy flag is the blocker
 *   - 500s   => (b), the endpoint type is the blocker
 *
 * Creates one throwaway form endpoint and one contact (a +alias of Mark's own
 * address). Both are deletable.
 */
const TEST_EMAIL = "mark+ctrl1@agilepainrelief.com";

async function main() {
  const c = new CakemailClient();

  const created = await c.rawRequest(
    "POST",
    `/lists/${NEWSLETTER_SUBSCRIBERS_LIST_ID}/forms`,
    { name: "TEMP control probe - delete me" },
  );
  console.log(`create endpoint: status ${created.status} ok=${created.ok}`);
  const form = (created.data as { data?: { id: string; submission_url: string } })?.data;
  if (!form?.submission_url) {
    console.log(JSON.stringify(created.data ?? created.error).slice(0, 500));
    return;
  }
  console.log(`  id=${form.id}`);

  const body = new FormData();
  body.append("email", TEST_EMAIL);
  body.append("custom_attributes[firstname]", "Mark");
  body.append("tags[ctrlprobe]", "true");

  const res = await fetch(form.submission_url, { method: "POST", body });
  console.log(`\nPOST to control endpoint as ${TEST_EMAIL}`);
  console.log(`  status ${res.status} ${res.statusText}`);
  console.log(`  body: ${(await res.text()).slice(0, 400)}`);

  await new Promise((r) => setTimeout(r, 4000));
  const lookup = await c.rawRequest(
    "GET",
    `/lists/${NEWSLETTER_SUBSCRIBERS_LIST_ID}/contacts?filter=${encodeURIComponent(`email==${TEST_EMAIL}`)}`,
  );
  console.log(`\nContact: ${JSON.stringify(lookup.data).slice(0, 800)}`);

  console.log(`\nCleaning up the throwaway endpoint...`);
  const del = await c.rawRequest(
    "DELETE",
    `/lists/${NEWSLETTER_SUBSCRIBERS_LIST_ID}/forms/${form.id}`,
  );
  console.log(`  delete: status ${del.status} ok=${del.ok}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

