/**
 * Cakemail hosted-form submission URL — SERVER-ONLY.
 *
 * This was previously two URLs exported from `shared/cakemail-constants.ts` and
 * POSTed to directly from the browser, which put the raw Cakemail URLs in the
 * client bundle. Bots scraped them and submitted junk straight to Cakemail,
 * bypassing any client-side guard, which a direct POST never reaches.
 *
 * The URL now lives here and is imported ONLY by `src/pages/api/newsletter-signup.ts`,
 * so the browser never sees it. The single public surface is that Turnstile-gated
 * endpoint; the function verifies the token, then forwards here.
 *
 * This form is bound to the Newsletter Subscribers list with double opt-in, and
 * serves the plain newsletter signups. Submissions to it are sent with NO tags
 * (see `cakemailFormFor` below) — the AI and quiz paths go to the staging form
 * instead. It replaces the old per-purpose forms, whose harvested URLs die when
 * those forms are deleted.
 */
export const CAKEMAIL_FORM_URL =
  'https://api.cakemail.dev/form_submission/9196ce583d2d3a93b44108dc596e09727d6db67786442cec4aac59e63cb83d8d9ff30f38ba5e6dbf83caeaf04b97280d';

/**
 * Hosted form bound to the SIGNUP STAGING list, used by the paths that need the
 * lead-magnet sequence and that carry tags: the quiz and the two AI forms.
 *
 * Staging exists because a hosted-form POST REPLACES a contact's whole tag set.
 * On Newsletter Subscribers that would wipe the Drip-migrated alumni / interest /
 * refresher-suppression tags; on staging the contact has no history to lose.
 * `npm run migrate-signups` then carries them onto Newsletter Subscribers through
 * the authenticated API, which merges. See the tag-hazard section in CLAUDE.md.
 *
 * MUST be created in the Cakemail UI, like the main-list form above, and must be
 * the page-builder kind whose URL looks like `form_submission/<hash>`. Creating
 * one through the API does not work, in either of the two available ways:
 * `POST /forms` (page-builder) 500s on create, and `POST /lists/{id}/forms`
 * creates a `subscription_forms/<hash>` endpoint that accepts the create call but
 * then 500s on every submission — verified 2026-08-05 against both a new list and
 * the known-good Newsletter Subscribers list, so it is the endpoint type at
 * fault, not the list.
 *
 * Left empty until that form exists. Empty is SAFE: `cakemailFormFor` falls back
 * to the main list with tags stripped and logs loudly. A dead URL here would be
 * far worse — the signup would 500 silently and the person would see success.
 */
export const CAKEMAIL_STAGING_FORM_URL = '';

/**
 * How a destination treats the `tags[<name>]=true` fields the client sent.
 * `strip` is not a nicety: a tagged POST to a Newsletter Subscribers form
 * silently destroys that contact's existing tags.
 */
export type TagPolicy = 'forward' | 'strip';

/**
 * Resolve where a signup goes and whether its tags may travel with it.
 *
 * - `newsletter` — straight onto Newsletter Subscribers, tags STRIPPED. These
 *   forms make a plain subscribe promise ("get your free copy", "join the
 *   waitlist") and are answered by the single welcome email that triggers on
 *   list-add. Their `Signup*` / `From*` tags have no consumer, and forwarding
 *   them would wipe whatever the contact already carries.
 * - `ai` / `quiz` — onto the staging list, tags forwarded. Harmless there, and
 *   the sequence and the migration both read them.
 *
 * Unknown or missing values fall through to the safe destination.
 */
export function cakemailFormFor(target: string | null): {
  url: string;
  tagPolicy: TagPolicy;
} {
  if (target === 'ai' || target === 'quiz') {
    // Fail SOFT, not closed: without a staging form we still take the signup —
    // on the main list, with tags stripped, so nothing is destroyed. Losing the
    // person would be worse than losing their sequence, but this is a
    // misconfiguration and needs to be shouted about.
    if (!CAKEMAIL_STAGING_FORM_URL) {
      console.error(
        `CAKEMAIL_STAGING_FORM_URL is unset; routing "${target}" signup to the main list untagged. ` +
          'The lead-magnet sequence will NOT fire for this contact.'
      );
      return { url: CAKEMAIL_FORM_URL, tagPolicy: 'strip' };
    }
    return { url: CAKEMAIL_STAGING_FORM_URL, tagPolicy: 'forward' };
  }
  return { url: CAKEMAIL_FORM_URL, tagPolicy: 'strip' };
}

