import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { SIGNUP_STAGING_LIST_ID, NEWSLETTER_SUBSCRIBERS_LIST_ID } from "../../shared/cakemail-constants";
const EMAIL = "mark+staging5@agilepainrelief.com";

async function show(c: CakemailClient, list: string, label: string) {
  const r = await c.rawRequest("GET",
    `/lists/${list}/contacts?filter=${encodeURIComponent(`email==${EMAIL}`)}`);
  const row = ((r.data as { data?: Array<Record<string, unknown>> })?.data ?? [])[0];
  console.log(`${label}: status=${row?.status} tags=${JSON.stringify(row?.tags)} attrs=${JSON.stringify(row?.custom_attributes)}`);
  return row;
}

async function main() {
  const c = new CakemailClient();
  console.log("=== after migration");
  await show(c, SIGNUP_STAGING_LIST_ID, "staging   ");
  const target = await show(c, NEWSLETTER_SUBSCRIBERS_LIST_ID, "newsletter");

  // THE claim the whole design rests on: does /tag MERGE or REPLACE?
  console.log("\n=== applying one extra tag via tagContactOnList (the merge test)");
  const res = await c.tagContactOnList(NEWSLETTER_SUBSCRIBERS_LIST_ID, target!.id as number, ["probe-merge-test"]);
  console.log(`  tagContactOnList ok=${res.ok} ${res.error ?? ""}`);
  await new Promise((r) => setTimeout(r, 3000));
  const after = await show(c, NEWSLETTER_SUBSCRIBERS_LIST_ID, "newsletter");
  const tags = (after?.tags as string[]) ?? [];
  const merged = tags.includes("sm-role-ai") && tags.includes("role-scrum-master") && tags.includes("probe-merge-test");
  console.log(`\n  MERGE CONFIRMED: ${merged}  (${tags.length} tags present)`);
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
