import "./load-env";
import { CakemailClient } from "./cakemail-client";
import { NEWSLETTER_SUBSCRIBERS_LIST_ID, SIGNUP_STAGING_LIST_ID } from "../../shared/cakemail-constants";

const OLD_LIST = "9452554";
const OLD_FORM = "vPgSlKQy0zBvQcImrQGH";
const TEST_EMAILS = ["mark+ctrl2@agilepainrelief.com", "mark+staging5@agilepainrelief.com"];

async function delContact(c: CakemailClient, list: string, email: string) {
  const r = await c.rawRequest("GET",
    `/lists/${list}/contacts?filter=${encodeURIComponent(`email==${email}`)}`);
  const row = ((r.data as { data?: Array<{ id: number }> })?.data ?? [])[0];
  if (!row) { console.log(`  ${email} on ${list}: not present`); return; }
  const d = await c.rawRequest("DELETE", `/lists/${list}/contacts/${row.id}`);
  console.log(`  ${email} on ${list}: delete status ${d.status} ok=${d.ok}`);
}

async function main() {
  const c = new CakemailClient();

  console.log("Test contacts:");
  for (const email of TEST_EMAILS) {
    for (const list of [NEWSLETTER_SUBSCRIBERS_LIST_ID, SIGNUP_STAGING_LIST_ID]) {
      await delContact(c, list, email);
    }
  }

  console.log("\nOld API-created form + list:");
  const df = await c.rawRequest("DELETE", `/forms/${OLD_FORM}`);
  console.log(`  form ${OLD_FORM}: status ${df.status} ok=${df.ok}`);
  const dl = await c.rawRequest("DELETE", `/lists/${OLD_LIST}`);
  console.log(`  list ${OLD_LIST}: status ${dl.status} ok=${dl.ok}`);

  const lists = await c.rawRequest("GET", "/lists?per_page=50");
  console.log(`\nRemaining lists:`);
  for (const l of (lists.data as { data?: Array<Record<string, unknown>> })?.data ?? []) {
    console.log(`  ${l.id}  ${l.name}`);
  }
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
